content.content:
{
 "nodes": {
  "identity": {
   "name": "identity",
   "tools": [
    {
     "type": "function",
     "config": {
      "timeoutMs": 12000,
      "maxRetries": 0
     },
     "function": {
      "name": "verify_identity",
      "handler": "__function__:api_call",
      "parameters": {
       "type": "object",
       "properties": {
        "url": {
         "type": "string",
         "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity"
        },
        "body": {
         "type": "object",
         "required": [
          "field",
          "answer"
         ],
         "properties": {
          "field": {
           "enum": [
            "date_of_birth",
            "phone_last4"
           ],
           "type": "string",
           "default": "{{field}}",
           "description": "Which answer this is."
          },
          "answer": {
           "type": "string",
           "default": "{{answer}}",
           "description": "date_of_birth as YYYY-MM-DD, phone_last4 as four digits."
          },
          "customer_id": {
           "type": "string",
           "default": "{{customer_id}}"
          }
         }
        },
        "method": {
         "type": "string",
         "default": "POST"
        },
        "headers": {
         "type": "object",
         "properties": {
          "Content-Type": {
           "type": "string",
           "default": "application/json"
          }
         }
        }
       }
      },
      "description": "Check one security answer. Call it once for each answer the customer gives."
     }
    },
    {
     "type": "function",
     "config": {
      "timeoutMs": 10000
     },
     "function": {
      "name": "end_call",
      "handler": "__function__:end_call",
      "parameters": {
       "type": "object",
       "properties": {
        "message_mode": {
         "type": "string",
         "default": "none"
        },
        "interruptible": {
         "type": "boolean",
         "default": true
        },
        "trigger_pattern": {
         "type": "string",
         "default": "Have a good day|have a good day"
        },
        "trigger_timeout": {
         "type": "number",
         "default": 3
