                                       mapping=[{"path": "data.ok", "variable": "rec_%d_ok" % i}])
            n["rec_%db" % i] = api_node("rec_%db" % i, rec_tool("rec_%db" % i, i), [always(nxt)],
                                        mapping=[{"path": "data.ok", "variable": "rec_%db_ok" % i}])
        n["summarize"] = code_node("summarize", SUMMARIZE_CODE, [always("note_gate_1")])
